export const CORE_SCHEMA = "\n      CREATE TABLE IF NOT EXISTS tasks (\n        id TEXT PRIMARY KEY,\n        title TEXT NOT NULL,\n        status TEXT NOT NULL CHECK(status IN ('open', 'done', 'archived')),\n        revision INTEGER NOT NULL DEFAULT 0,\n        created_at TEXT NOT NULL,\n        updated_at TEXT NOT NULL\n      );\n      CREATE TABLE IF NOT EXISTS task_facts (\n        id TEXT PRIMARY KEY,\n        task_id TEXT NOT NULL REFERENCES tasks(id),\n        kind TEXT NOT NULL,\n        text TEXT NOT NULL,\n        source TEXT NOT NULL,\n        source_ref TEXT,\n        occurred_at TEXT NOT NULL,\n        created_at TEXT NOT NULL\n      );\n      CREATE INDEX IF NOT EXISTS idx_task_facts_task ON task_facts(task_id, occurred_at);\n      CREATE TABLE IF NOT EXISTS task_projections (\n        task_id TEXT PRIMARY KEY REFERENCES tasks(id),\n        summary TEXT,\n        next_step TEXT,\n        open_questions_json TEXT NOT NULL DEFAULT '[]',\n        blockers_json TEXT NOT NULL DEFAULT '[]',\n        artifacts_json TEXT NOT NULL DEFAULT '[]',\n        updated_at TEXT NOT NULL\n      );\n      CREATE TABLE IF NOT EXISTS proposals (\n        id TEXT PRIMARY KEY,\n        task_id TEXT NOT NULL REFERENCES tasks(id),\n        base_revision INTEGER NOT NULL,\n        model TEXT NOT NULL,\n        rationale TEXT NOT NULL,\n        confidence REAL NOT NULL,\n        changes_json TEXT NOT NULL,\n        status TEXT NOT NULL CHECK(status IN ('pending', 'approved', 'applied', 'rejected', 'conflicted')),\n        created_at TEXT NOT NULL,\n        resolved_at TEXT\n        ,idempotency_key TEXT UNIQUE\n      );\n      CREATE INDEX IF NOT EXISTS idx_proposals_idempotency ON proposals(idempotency_key);\n      CREATE TABLE IF NOT EXISTS proposal_evidence (\n        proposal_id TEXT NOT NULL REFERENCES proposals(id),\n        evidence_ref TEXT NOT NULL,\n        kind TEXT NOT NULL,\n        text TEXT NOT NULL,\n        source TEXT NOT NULL,\n        source_ref TEXT,\n        PRIMARY KEY(proposal_id, evidence_ref)\n      );\n      CREATE TABLE IF NOT EXISTS proposal_approvals (\n        id TEXT PRIMARY KEY,\n        proposal_id TEXT NOT NULL UNIQUE REFERENCES proposals(id),\n        proposal_hash TEXT NOT NULL,\n        actor TEXT NOT NULL,\n        created_at TEXT NOT NULL\n      );\n      CREATE TABLE IF NOT EXISTS application_receipts (\n        id TEXT PRIMARY KEY,\n        proposal_id TEXT NOT NULL UNIQUE REFERENCES proposals(id),\n        approval_id TEXT NOT NULL REFERENCES proposal_approvals(id),\n        task_id TEXT NOT NULL REFERENCES tasks(id),\n        before_revision INTEGER NOT NULL,\n        after_revision INTEGER NOT NULL,\n        fields_json TEXT NOT NULL,\n        created_at TEXT NOT NULL\n      );\n      CREATE TABLE IF NOT EXISTS kernel_events (\n        sequence INTEGER PRIMARY KEY AUTOINCREMENT,\n        id TEXT NOT NULL UNIQUE,\n        task_id TEXT,\n        type TEXT NOT NULL,\n        payload_json TEXT NOT NULL,\n        created_at TEXT NOT NULL\n      );\n      CREATE TABLE IF NOT EXISTS application_snapshots (\n        proposal_id TEXT PRIMARY KEY REFERENCES proposals(id),\n        before_json TEXT NOT NULL,\n        after_json TEXT NOT NULL\n      );\n    ";
